R,C=20,11
pts=[(0,5),(2,3),(4,1),(4,7),(5,8),(6,7),(6,8),(7,3),(8,1),(8,8),(9,5),(10,2),(10,10),(11,3),(12,5),(12,9),(14,0),(14,7),(15,2),(15,8),(17,2),(17,7),(17,8),(18,1),(18,6),(18,7),(19,1),(19,4)]
grid=[[4]*C for _ in range(R)]
for r,c in pts: grid[r][c]=5
for r in range(R):
    cs=[c for rr,c in pts if rr==r]
    if len(cs)>1:
        for c in range(min(cs)+1,max(cs)):
            if grid[r][c]==4: grid[r][c]=3
for c in range(C):
    rs=[r for r,cc in pts if cc==c]
    if len(rs)>1:
        for r in range(min(rs)+1,max(rs)):
            if grid[r][c]==4: grid[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in grid))
